#include <iostream>
#include <map>
#include <functional>
using namespace std;

class Router {
    map<string, function<void()>> routes;
public:
    void get(const string& path, function<void()> handler) {
        routes[path] = handler;
    }
    void dispatch(const string& path) {
        auto it = routes.find(path);
        if (it != routes.end()) it->second();
        else cout << "404 Not Found" << endl;
    }
};

int main() {
    Router r;
    r.get("/", []() { cout << "Home" << endl; });
    r.get("/about", []() { cout << "About" << endl; });
    r.get("/api", []() { cout << "API" << endl; });
    r.dispatch("/about");
    r.dispatch("/unknown");
    return 0;
}
